import backend.util.DBConnection; import java.sql.*; public class CheckCols3 { public static void main(String[] args) throws Exception { Connection conn = DBConnection.getConnection(); Statement stmt = conn.createStatement(); ResultSet rs = stmt.executeQuery("SELECT * FROM students LIMIT 1"); ResultSetMetaData rsmd = rs.getMetaData(); int numCols = rsmd.getColumnCount(); for (int i = 1; i <= numCols; i++) { System.out.println(rsmd.getColumnName(i)); } } }
